(()=>{
 const add=window.POLIS_ADD_SYSTEM;if(!add)return;
 add({id:'kant',prefix:'ka',author:'Immanuel Kant',work:'Metafísica de las costumbres + Hacia la paz perpetua',workId:'kant-right',icon:'⚖️',tagline:'Libertad jurídica, derecho, república, publicidad y cosmopolitismo',lessons:[
  {title:'Freiheit: el derecho parte de libertad externa',hook:'La teoría jurídica kantiana pregunta cómo pueden coexistir libertades sin que una destruya la de otra.',body:'En la Doctrina del Derecho, Freiheit es el único derecho innato: independencia respecto del arbitrio constrictivo de otro, compatible con la libertad de todos según una ley universal.',relation:['libertad externa','igualdad jurídica','reciprocidad','derecho innato'],terms:[['Freiheit','','libertad'],['äußere Freiheit','','libertad externa'],['angeborenes Recht','','derecho innato'],['Willkür','','arbitrio / capacidad de elección']],quote:{original:'Freiheit ... ist dieses einzige, ursprüngliche, jedem Menschen ... zustehende Recht.',translation:'«La libertad es el único derecho originario que corresponde a todo ser humano».',source:'Metaphysik der Sitten, Rechtslehre, Einleitung',note:'Se trata de libertad externa en relación con el arbitrio de otros.'},example:'Mi libertad de moverme no puede incluir un derecho universal a encerrar arbitrariamente a otros.',tip:'Kant no parte de maximizar bienestar, sino de compatibilizar libertades externas.',discovery:{scenario:'Dos personas reclaman libertades incompatibles: una quiere decidir por la otra sin su consentimiento.',question:'¿Qué problema debe resolver el derecho?',options:['Compatibilizar libertades externas','Maximizar prestigio','Eliminar toda coerción'],answer:0,reveal:'El derecho regula relaciones externas entre arbitrios libres.'},check:{prompt:'¿Qué es el derecho innato básico?',options:['Libertad compatible con la libertad de todos','Propiedad ilimitada','Obediencia pasiva'],answer:0}},
  {title:'Recht: condiciones de coexistencia de arbitrios',hook:'El derecho no juzga intenciones interiores, sino relaciones externas entre elecciones libres.',body:'Recht es el conjunto de condiciones bajo las cuales el arbitrio de uno puede coexistir con el arbitrio de otro según una ley universal de libertad. Esto permite distinguir juridicidad de virtud moral interior.',relation:['Willkür de A','Willkür de B','ley universal','coexistencia jurídica'],terms:[['Recht','','derecho'],['Bedingungen','','condiciones'],['allgemeines Gesetz','','ley universal'],['Koexistenz','','coexistencia']],quote:{original:'Das Recht ist ... der Inbegriff der Bedingungen, unter denen die Willkür des einen ... zusammen vereinigt werden kann.',translation:'«El derecho es el conjunto de condiciones bajo las cuales el arbitrio de uno puede coexistir con el de otro».',source:'Metaphysik der Sitten, Rechtslehre, Einleitung B',note:'La definición es relacional y externa.'},example:'El derecho puede prohibir fraude sin exigir que el comerciante actúe por puro deber moral.',tip:'Separá legalidad externa de moralidad de motivos.',discovery:{scenario:'Una norma regula contratos sin investigar si quienes cumplen son moralmente virtuosos.',question:'¿Puede seguir siendo jurídica?',options:['Sí','No','Solo si todos actúan por deber'],answer:0,reveal:'El derecho se ocupa de coexistencia externa, no de santidad interior.'},check:{prompt:'¿Qué define Recht?',options:['Condiciones universales de coexistencia de arbitrios','La intención moral privada','El deseo mayoritario'],answer:0}},
  {title:'Principio universal del derecho',hook:'Una acción es justa si su máxima externa puede coexistir con la libertad de todos.',body:'El principio universal de derecho evalúa la compatibilidad de una acción con una libertad general. La coerción jurídica puede ser legítima cuando impide un impedimento injusto a la libertad: es una “coerción de la coerción”.',relation:['acción externa','compatibilidad universal','impedimento injusto','coerción jurídica'],terms:[['allgemeines Rechtsprinzip','','principio universal del derecho'],['Zwang','','coerción'],['Hindernis','','impedimento'],['Freiheitsgesetz','','ley de libertad']],quote:{original:'Eine jede Handlung ist recht, die ... mit jedermanns Freiheit ... zusammen bestehen kann.',translation:'«Es justa toda acción cuya libertad pueda coexistir con la libertad de todos».',source:'Metaphysik der Sitten, Rechtslehre, Einleitung C',note:'La coerción legítima restaura condiciones de libertad universal.'},example:'Impedir físicamente que alguien secuestre a otro limita al agresor para proteger la libertad común.',tip:'La coerción no es automáticamente contraria a libertad jurídica.',discovery:{scenario:'Una persona usa su libertad para encerrar arbitrariamente a otra.',question:'¿Puede el derecho coaccionarla?',options:['Sí','No, toda coerción viola libertad','Solo si lo pide una mayoría'],answer:0,reveal:'Coaccionar un impedimento injusto puede defender libertad universal.'},check:{prompt:'¿Cuándo es legítima coerción jurídica?',options:['Cuando impide un impedimento contrario a libertad universal','Siempre que la ordene un gobernante','Nunca'],answer:0}},
  {title:'Salir del estado de naturaleza',hook:'Derechos privados requieren una condición pública que los determine y garantice de modo omnilateral.',body:'En el estado de naturaleza puede haber pretensiones de derecho privado, pero permanecen provisionales porque cada uno juzga unilateralmente. Existe un deber jurídico de entrar en un estado civil con leyes públicas, juez y coerción común.',relation:['pretensiones privadas','juicio unilateral','estado civil','derecho público'],terms:[['Naturzustand','','estado de naturaleza'],['bürgerlicher Zustand','','estado civil'],['öffentliches Recht','','derecho público'],['provisorisch','','provisional']],quote:{original:'du sollst ... aus dem Naturzustande ... herausgehen',translation:'«Debes salir del estado de naturaleza».',source:'Metaphysik der Sitten, Rechtslehre §44',note:'El paso al estado civil es un deber de justicia pública.'},example:'Dos propietarios no pueden resolver definitivamente un límite si cada uno es juez final de su propio derecho.',tip:'La publicidad institucional transforma posesión provisional en derecho perentorio.',discovery:{scenario:'Dos personas reclaman la misma tierra y cada una se declara juez definitivo.',question:'¿Qué falta?',options:['Estado civil público','Más propiedad privada','Virtù'],answer:0,reveal:'La unilateralidad del juicio hace provisional el derecho.'},check:{prompt:'¿Por qué salir del estado de naturaleza?',options:['Para convertir pretensiones unilaterales en derecho público común','Para renunciar a libertad','Para crear desigualdad moral'],answer:0}},
  {title:'Contrato originario como idea de razón',hook:'Kant no necesita probar un contrato histórico firmado: lo usa como criterio normativo de legislación.',body:'El ursprünglicher Vertrag es una idea de razón que obliga a legislar como si las leyes pudieran haber surgido de la voluntad unida de todo un pueblo. Su función es probar legitimidad, no narrar un hecho fundacional.',relation:['legislación','idea del contrato','voluntad unida posible','legitimidad'],terms:[['ursprünglicher Vertrag','','contrato originario'],['Idee der Vernunft','','idea de la razón'],['vereinigter Volkswille','','voluntad unida del pueblo'],['Legitimität','','legitimidad']],quote:{original:'der ursprüngliche Vertrag ... ist bloß eine Idee der Vernunft',translation:'«El contrato originario es meramente una idea de la razón».',source:'Über den Gemeinspruch, II',note:'No es una hipótesis histórica que dependa de encontrar un documento original.'},example:'Una ley sería sospechosa si ningún ciudadano pudiera razonablemente consentirla como miembro igual del cuerpo político.',tip:'Usá el contrato como test de legitimidad, no como arqueología.',discovery:{scenario:'Un historiador demuestra que nunca hubo una firma contractual fundacional.',question:'¿Refuta el contrato kantiano?',options:['No','Sí','Solo en monarquía'],answer:0,reveal:'Su función es normativa como idea de razón.'},check:{prompt:'¿Qué es el contrato originario?',options:['Una idea normativa para juzgar legislación','Un documento histórico necesario','Un pacto secreto'],answer:0}},
  {title:'Republikanische Verfassung',hook:'La paz externa depende también de una constitución interna compatible con libertad, dependencia de una ley común e igualdad.',body:'En Hacia la paz perpetua, la constitución republicana separa autoridad legislativa y ejecutiva y hace que quienes soportan costos de guerra participen de la decisión política. República no equivale simplemente a democracia directa.',relation:['libertad jurídica','ley común','igualdad','constitución republicana'],terms:[['republikanische Verfassung','','constitución republicana'],['Gewaltenteilung','','separación de poderes'],['Bürger','','ciudadano'],['Repräsentation','','representación']],quote:{original:'Die bürgerliche Verfassung in jedem Staate soll republikanisch sein.',translation:'«La constitución civil de cada Estado debe ser republicana».',source:'Zum ewigen Frieden, primer artículo definitivo',note:'Kant contrapone republicanismo y despotismo, no república y monarquía sin más.'},example:'Un monarca constitucional representativo puede ser “republicano” en sentido kantiano si gobierna mediante leyes y separación funcional.',tip:'No identifiques republicanismo kantiano con una forma electoral contemporánea específica.',discovery:{scenario:'Quien decide una guerra no soporta ninguno de sus costos y gobierna sin leyes comunes.',question:'¿Qué diseño kantiano falta?',options:['Constitución republicana','Estado de naturaleza permanente','Tiranía platónica'],answer:0,reveal:'El republicanismo conecta decisión, representación y responsabilidad pública.'},check:{prompt:'¿Qué exige el republicanismo kantiano?',options:['Libertad jurídica, ley común e igualdad con gobierno no despótico','Democracia directa obligatoria','Ausencia de ejecutivo'],answer:0}},
  {title:'Principio de publicidad',hook:'Una máxima política que solo funciona si permanece secreta revela una tensión con el derecho.',body:'Kant formula un principio trascendental del derecho público: acciones relativas al derecho ajeno son injustas si su máxima no puede soportar publicidad. No toda diplomacia debe ser transparente, pero una regla cuya eficacia depende de engañar a quienes obliga es normativamente sospechosa.',relation:['máxima política','prueba de publicidad','posible consentimiento','derecho público'],terms:[['Publizität','','publicidad'],['Maxime','','máxima'],['öffentliches Recht','','derecho público'],['Transzendentalformel','','fórmula trascendental']],quote:{original:'Alle ... Maximen, die sich nicht mit der Publizität vertragen, sind unrecht.',translation:'«Todas las máximas incompatibles con la publicidad son injustas».',source:'Zum ewigen Frieden, Apéndice II',note:'La prueba apunta a máximas, no a divulgar cada dato gubernamental.'},example:'Una política fiscal puede fracasar moralmente si solo funciona ocultando deliberadamente que expropia a un grupo sin regla general defendible.',tip:'Preguntá si la máxima puede declararse públicamente sin destruir su propia legitimidad.',discovery:{scenario:'Un gobierno adopta una regla que solo funciona si los ciudadanos nunca descubren que serán engañados.',question:'¿Qué test falla?',options:['Publizität','Autarkeia','Conatus'],answer:0,reveal:'La dependencia estructural del secreto revela injusticia de la máxima.'},check:{prompt:'¿Qué prueba el principio de publicidad?',options:['Si una máxima política puede hacerse pública sin contradecir el derecho','Si toda reunión es abierta','Si el gobernante es popular'],answer:0}},
  {title:'Weltbürgerrecht y paz perpetua',hook:'La paz no se agota en derecho interno: requiere relaciones interestatales y un mínimo derecho cosmopolita.',body:'Kant articula derecho estatal, derecho de gentes y Weltbürgerrecht. La hospitalidad universal no es derecho a instalarse en cualquier lugar, sino a no ser tratado hostilmente al presentarse pacíficamente. La paz perpetua es un proyecto jurídico regulativo.',relation:['Estados republicanos','federación pacífica','hospitalidad','derecho cosmopolita'],terms:[['Weltbürgerrecht','','derecho cosmopolita'],['Hospitalität','','hospitalidad'],['Völkerbund','','federación de pueblos'],['ewiger Friede','','paz perpetua']],quote:{original:'Das Weltbürgerrecht soll auf Bedingungen der allgemeinen Hospitalität eingeschränkt sein.',translation:'«El derecho cosmopolita debe limitarse a condiciones de hospitalidad universal».',source:'Zum ewigen Frieden, tercer artículo definitivo',note:'Hospitalidad no equivale a derecho automático de residencia permanente.'},example:'Un náufrago extranjero no adquiere propiedad sobre el país al llegar, pero tampoco debe ser tratado como enemigo por presentarse pacíficamente.',tip:'Cerrá el sistema en tres escalas: ciudadano, Estado y orden cosmopolita.',discovery:{scenario:'Estados republicanos comercian y cooperan, pero tratan a todo extranjero pacífico como enemigo sin excepción.',question:'¿Qué dimensión falta?',options:['Weltbürgerrecht','Ley natural tomista','Voluntad general'],answer:0,reveal:'La paz jurídica requiere también condiciones cosmopolitas de encuentro.'},check:{prompt:'¿Qué añade el derecho cosmopolita?',options:['Reglas mínimas para relaciones entre personas y Estados más allá de ciudadanía nacional','Un Estado mundial despótico obligatorio','Abolición de todo derecho interno'],answer:0}}
 ]});

 add({id:'hegel',prefix:'he',author:'G. W. F. Hegel',work:'Principios de la filosofía del derecho',workId:'philosophy-right',icon:'🌀',tagline:'Libertad realizada, propiedad, sociedad civil, eticidad y Estado',lessons:[
  {title:'Das Reich der verwirklichten Freiheit',hook:'El derecho es el ámbito donde la libertad deja de ser mera posibilidad interior y adquiere existencia objetiva.',body:'Para Hegel, el sistema del derecho es “el reino de la libertad realizada”. La voluntad libre necesita instituciones, prácticas y reconocimientos objetivos. Libertad no equivale a elegir arbitrariamente entre opciones.',relation:['voluntad libre','objetivación','instituciones de derecho','libertad realizada'],terms:[['Freiheit','','libertad'],['freier Wille','','voluntad libre'],['Recht','','derecho'],['verwirklichte Freiheit','','libertad realizada']],quote:{original:'Das Rechtssystem ist das Reich der verwirklichten Freiheit.',translation:'«El sistema del derecho es el reino de la libertad realizada».',source:'Grundlinien der Philosophie des Rechts §4',note:'La libertad requiere forma objetiva, no solo convicción subjetiva.'},example:'Poder elegir contratos carece de sentido si nadie reconoce personalidad jurídica ni existen instituciones que hagan valer acuerdos.',tip:'Leé cada esfera como una forma más concreta de libertad.',discovery:{scenario:'Una persona se siente interiormente libre pero carece de toda personalidad jurídica y reconocimiento social.',question:'¿Está plenamente realizada su libertad?',options:['No','Sí, la libertad es solo interior','Solo si tiene riqueza'],answer:0,reveal:'La libertad necesita objetivarse en derecho e instituciones.'},check:{prompt:'¿Qué es el sistema del derecho?',options:['El reino de libertad realizada','Una limitación puramente externa','La negación de toda voluntad'],answer:0}},
  {title:'Persona y propiedad: libertad abstracta',hook:'La primera forma de libertad objetiva es reconocerse y ser reconocido como persona capaz de poseer cosas.',body:'En el abstraktes Recht, la persona da existencia externa a su voluntad mediante Eigentum. La propiedad no se justifica primero por utilidad económica, sino como primera objetivación de personalidad libre.',relation:['Person','voluntad','Eigentum','reconocimiento jurídico'],terms:[['Person','','persona jurídica'],['abstraktes Recht','','derecho abstracto'],['Eigentum','','propiedad'],['Besitz','','posesión']],quote:{original:'Die Person muß sich eine äußere Sphäre ihrer Freiheit geben.',translation:'«La persona debe darse una esfera externa de su libertad».',source:'Grundlinien §41',note:'La propiedad aparece como objetivación inicial de voluntad libre.'},example:'Apropiarse de una cosa permite marcar externamente “esto está bajo mi voluntad”, siempre dentro de reconocimiento jurídico recíproco.',tip:'No reduzcas la propiedad hegeliana a incentivo económico.',discovery:{scenario:'Una persona es reconocida como agente pero no puede objetivar ninguna decisión en el mundo externo.',question:'¿Qué esfera falta?',options:['Eigentum','Soberanía de excepción','Pitié'],answer:0,reveal:'La propiedad es una primera esfera externa de libertad.'},check:{prompt:'¿Qué función filosófica cumple la propiedad?',options:['Objetivar externamente la voluntad personal','Maximizar utilidad agregada','Eliminar reconocimiento'],answer:0}},
  {title:'Moralität: intención y subjetividad',hook:'La libertad no se agota en derechos externos: el sujeto reclama ser autor consciente de sus acciones.',body:'La Moralität introduce intención, propósito, bienestar y conciencia. Pero si la subjetividad se absolutiza, puede convertir convicción privada en tribunal supremo sin mediación institucional.',relation:['sujeto moral','intención','conciencia','límite de subjetividad aislada'],terms:[['Moralität','','moralidad'],['Absicht','','intención'],['Gewissen','','conciencia'],['Wohl','','bienestar']],quote:{original:'Das Recht des subjektiven Willens ...',translation:'«El derecho de la voluntad subjetiva ...».',source:'Grundlinien §§105–140',note:'Hegel reconoce la subjetividad moderna y a la vez critica su aislamiento.'},example:'Un funcionario no puede justificar cualquier acto ilegal diciendo simplemente que su conciencia privada lo considera bueno.',tip:'Moralidad es un avance respecto del derecho abstracto, pero todavía no la síntesis institucional.',discovery:{scenario:'Una persona considera legítimo todo lo que su conciencia individual aprueba, sin aceptar criterios sociales o jurídicos.',question:'¿Qué unilateralidad aparece?',options:['Subjetividad moral aislada','Eticidad plenamente realizada','Libertad cosmopolita'],answer:0,reveal:'La Moralität necesita integrarse en formas éticas objetivas.'},check:{prompt:'¿Qué introduce Moralität?',options:['Intención y subjetividad responsable','Solo propiedad','Soberanía popular directa'],answer:0}},
  {title:'Sittlichkeit: libertad en instituciones vividas',hook:'La eticidad supera la oposición entre ley externa y convicción privada mediante prácticas sociales racionales.',body:'Sittlichkeit es la idea de libertad hecha mundo de costumbres e instituciones. Familia, sociedad civil y Estado no son simples restricciones externas: son contextos en los que identidades y obligaciones libres adquieren contenido.',relation:['libertad subjetiva','normas objetivas','hábitos e instituciones','Sittlichkeit'],terms:[['Sittlichkeit','','eticidad'],['sittliche Idee','','idea ética'],['Institution','','institución'],['Gewohnheit','','hábito / costumbre']],quote:{original:'Die Sittlichkeit ist die Idee der Freiheit.',translation:'«La eticidad es la idea de la libertad».',source:'Grundlinien §142',note:'La libertad se vuelve sustancial al encarnarse en prácticas y relaciones reconocidas.'},example:'Ser miembro de una familia o ciudadano no es solo sufrir obligaciones: también adquirir capacidades y reconocimiento que hacen posible actuar libremente.',tip:'Evitá leer “institución” como mero límite negativo.',discovery:{scenario:'Una teoría enfrenta siempre individuo libre contra toda institución como si fueran enemigos externos.',question:'¿Qué objeción hegeliana cabe?',options:['Las instituciones pueden realizar libertad','Toda institución es tiranía','La libertad solo existe antes de sociedad'],answer:0,reveal:'Sittlichkeit integra subjetividad y orden objetivo.'},check:{prompt:'¿Qué es Sittlichkeit?',options:['Libertad encarnada en instituciones y prácticas','Moral privada aislada','Obediencia ciega'],answer:0}},
  {title:'Familie: unidad ética inmediata',hook:'La familia es la primera esfera de eticidad, basada en una unidad afectiva que relativiza la individualidad aislada.',body:'En la Familie, miembros se experimentan como parte de una unidad. Matrimonio, patrimonio familiar y educación de hijos forman una estructura ética que, al madurar los hijos, se disuelve hacia personas independientes.',relation:['amor','unidad familiar','educación','salida a individualidad'],terms:[['Familie','','familia'],['Liebe','','amor'],['Ehe','','matrimonio'],['Erziehung','','educación']],quote:{original:'Die Familie ... hat die Liebe ... zu ihrer Bestimmung.',translation:'«La familia tiene el amor como su determinación».',source:'Grundlinien §158',note:'La unidad familiar es inmediata y no sustituye sociedad civil o Estado.'},example:'Los hijos son formados dentro de la familia precisamente para convertirse después en personas independientes.',tip:'La familia es necesaria pero no suficiente para la libertad moderna.',discovery:{scenario:'Una comunidad pretende mantener a todos sus miembros permanentemente en relaciones familiares de dependencia.',question:'¿Qué desarrollo bloquea?',options:['La individualidad que entra en sociedad civil','La eticidad familiar','La propiedad de la familia'],answer:0,reveal:'La familia produce individuos que luego salen hacia relaciones universales.'},check:{prompt:'¿Qué principio organiza la familia?',options:['Unidad ética inmediata basada en amor','Competencia universal de mercado','Enemistad política'],answer:0}},
  {title:'Bürgerliche Gesellschaft: necesidades y particularidad',hook:'La sociedad civil libera particularidad e intercambio, pero produce interdependencia y desigualdades que no corrige automáticamente.',body:'La bürgerliche Gesellschaft es el sistema de necesidades donde individuos persiguen fines privados mediante división del trabajo, mercado y derecho. Esa interdependencia produce riqueza, pero también pobreza y vulnerabilidad.',relation:['necesidades particulares','división del trabajo','mercado interdependiente','desigualdad / pobreza'],terms:[['bürgerliche Gesellschaft','','sociedad civil'],['System der Bedürfnisse','','sistema de necesidades'],['Arbeitsteilung','','división del trabajo'],['Pöbel','','plebe / pauperización social']],quote:{original:'die bürgerliche Gesellschaft ... das System der Bedürfnisse',translation:'«La sociedad civil ... el sistema de las necesidades».',source:'Grundlinien §§182–208',note:'No es sinónimo simple de “sociedad” ni de esfera voluntaria contemporánea.'},example:'El mercado conecta millones de intereses privados, pero puede dejar grupos sin medios estables de pertenencia y reconocimiento.',tip:'La particularidad moderna es productiva y contradictoria.',discovery:{scenario:'Un mercado muy productivo aumenta riqueza total mientras crea pobreza persistente y exclusión.',question:'¿Es una anomalía externa al sistema?',options:['No, expresa tensiones internas de la sociedad civil','Sí, el mercado hegeliano elimina pobreza','Solo depende de moral privada'],answer:0,reveal:'La sociedad civil genera interdependencia junto con riesgos sociales.'},check:{prompt:'¿Qué caracteriza a bürgerliche Gesellschaft?',options:['Sistema de necesidades, trabajo e intereses particulares interdependientes','Unidad familiar inmediata','Estado de naturaleza'],answer:0}},
  {title:'Polizei y Korporation: mediaciones sociales',hook:'Las contradicciones de sociedad civil requieren instituciones que regulen riesgos y reconstruyan pertenencia.',body:'Polizei en sentido amplio incluye regulación y previsión pública; Korporationen organizan profesiones y dan reconocimiento a miembros. No sustituyen al Estado, pero median entre individuo privado y universalidad política.',relation:['riesgos de mercado','Polizei','Korporation','integración social'],terms:[['Polizei','','administración / policía social'],['Korporation','','corporación'],['Vorsorge','','previsión'],['Anerkennung','','reconocimiento']],quote:{original:'Die Korporation ist ... die zweite ... Familie.',translation:'«La corporación es ... una segunda familia».',source:'Grundlinien §252',note:'La metáfora indica pertenencia mediada dentro de sociedad civil.'},example:'Una asociación profesional puede dar identidad, capacitación y protección frente a vulnerabilidad individual del mercado.',tip:'Hegel construye mediaciones entre mercado y Estado.',discovery:{scenario:'Trabajadores atomizados enfrentan riesgos comunes pero carecen de toda organización intermedia.',question:'¿Qué mediación hegeliana falta?',options:['Korporation','Estado de naturaleza','Volonté générale'],answer:0,reveal:'Las corporaciones reconstruyen pertenencia dentro de la sociedad civil.'},check:{prompt:'¿Qué función cumplen Polizei y Korporation?',options:['Mediar riesgos e integración social','Eliminar sociedad civil','Crear soberanía personal'],answer:0}},
  {title:'Der Staat: universalidad concreta',hook:'El Estado racional integra familia y sociedad civil sin simplemente absorberlas.',body:'Hegel define al Staat como Wirklichkeit der sittlichen Idee. Su función no es aplastar particularidades, sino organizarlas dentro de una universalidad institucional donde ciudadano reconoce sus fines privados y comunes como momentos de una totalidad política.',relation:['familia','sociedad civil','mediaciones','Estado ético'],terms:[['Staat','','Estado'],['Wirklichkeit','','actualidad efectiva'],['sittliche Idee','','idea ética'],['Allgemeinheit','','universalidad']],quote:{original:'Der Staat ist die Wirklichkeit der sittlichen Idee.',translation:'«El Estado es la realidad efectiva de la idea ética».',source:'Grundlinien §257',note:'“Wirklichkeit” no significa que cualquier Estado existente sea racional por definición.'},example:'Un Estado racional debe incorporar derechos individuales, sociedad civil y representación institucional en lugar de destruirlos.',tip:'No conviertas la frase en apología automática de todo poder estatal existente.',discovery:{scenario:'Un régimen destruye familia, asociaciones, derecho privado y toda autonomía social en nombre del Estado.',question:'¿Realiza la integración hegeliana?',options:['No','Sí necesariamente','Solo si es monarquía'],answer:0,reveal:'El Estado ético presupone y media esferas previas de libertad.'},check:{prompt:'¿Qué es el Estado racional?',options:['Universalidad concreta que integra esferas de eticidad','Poder arbitrario sin sociedad civil','Simple contrato de individuos'],answer:0}}
 ]});

 add({id:'schmitt',prefix:'sc',author:'Carl Schmitt',work:'Teología política + El concepto de lo político + Teoría de la Constitución',workId:'concept-political',icon:'⚡',tagline:'Excepción, decisión, amigo/enemigo, representación y poder constituyente',lessons:[
  {title:'Soberano es quien decide sobre la excepción',hook:'Schmitt comienza donde la norma deja de indicar por sí sola quién puede salvar el orden.',body:'La definición de soberanía se concentra en Ausnahmezustand: una situación extrema en la que debe decidirse si existe una excepción y qué medidas requiere. La decisión revela qué instancia posee autoridad final.',relation:['orden normal','crisis extrema','decisión sobre excepción','soberanía'],terms:[['Souverän','','soberano'],['Ausnahmezustand','','estado de excepción'],['Entscheidung','','decisión'],['Souveränität','','soberanía']],quote:{original:'Souverän ist, wer über den Ausnahmezustand entscheidet.',translation:'«Soberano es quien decide sobre el estado de excepción».',source:'Politische Theologie, cap. 1',note:'La frase define soberanía por una competencia límite, no por administración cotidiana.'},example:'Una constitución distribuye competencias ordinarias, pero una crisis obliga a decidir quién puede suspender temporalmente procedimientos.',tip:'La pregunta schmittiana es quién decide cuando la norma no resuelve el caso.',discovery:{scenario:'Todas las instituciones discuten si existe una emergencia, pero una sola puede decidirlo de manera final y efectiva.',question:'¿Qué revela esa capacidad?',options:['Soberanía','Neutralidad total','Voluntad general'],answer:0,reveal:'Decidir sobre la excepción identifica la instancia soberana.'},check:{prompt:'¿Cómo define Schmitt al soberano?',options:['Quien decide sobre la excepción','Quien posee más riqueza','Quien interpreta todas las normas sin poder decisorio'],answer:0}},
  {title:'La excepción revela el fundamento del orden',hook:'El caso normal puede ocultar cuánto depende la norma de una decisión que instituye y preserva normalidad.',body:'Schmitt sostiene que la excepción es más interesante que el caso normal porque muestra que una norma jurídica presupone una situación normal. Ninguna regla puede anticipar completamente una crisis radical.',relation:['norma','presupuesto de normalidad','excepción','decisión fundante'],terms:[['Norm','','norma'],['Normalfall','','caso normal'],['Ausnahme','','excepción'],['Ordnung','','orden']],quote:{original:'Die Ausnahme ist interessanter als der Normalfall.',translation:'«La excepción es más interesante que el caso normal».',source:'Politische Theologie, cap. 1',note:'“Interesante” significa teóricamente reveladora del fundamento del orden.'},example:'Una regla sobre sesiones parlamentarias presupone que exista un parlamento capaz de reunirse y un territorio bajo control.',tip:'Detectá qué condiciones normales presupone cada norma.',discovery:{scenario:'Una ley funciona perfectamente mientras existe paz, pero nada dice sobre una guerra civil que destruye las instituciones que deben aplicarla.',question:'¿Qué muestra la crisis?',options:['Los presupuestos de normalidad de la norma','Que las normas nunca importan','Que toda política es económica'],answer:0,reveal:'La excepción revela condiciones que el funcionamiento ordinario daba por supuestas.'},check:{prompt:'¿Qué enseña la excepción?',options:['Que la norma presupone un orden normal que no puede producir por sí sola','Que todo derecho es inútil','Que la decisión cotidiana debe ser arbitraria'],answer:0}},
  {title:'Freund und Feind',hook:'Lo político posee un criterio específico de intensidad: distinguir amigo y enemigo público.',body:'Schmitt no define lo político por un contenido fijo como economía o moral. Una oposición se vuelve política cuando alcanza intensidad suficiente para agrupar colectividades como Freund y Feind ante posibilidad real de conflicto.',relation:['oposición social','intensificación','Freund/Feind','lo político'],terms:[['Freund','','amigo'],['Feind','','enemigo'],['das Politische','','lo político'],['Unterscheidung','','distinción']],quote:{original:'Die spezifisch politische Unterscheidung ... ist die Unterscheidung von Freund und Feind.',translation:'«La distinción específicamente política es la de amigo y enemigo».',source:'Der Begriff des Politischen, 1932',note:'El enemigo es público; no significa odiar personalmente a cada adversario.'},example:'Una disputa religiosa puede permanecer teológica o volverse política si divide colectividades dispuestas a enfrentarse existencialmente.',tip:'El contenido puede variar; importa la intensidad de agrupación.',discovery:{scenario:'Un desacuerdo cultural organiza dos colectividades que empiezan a tratarse como amenazas existenciales.',question:'¿Qué transformación ocurre?',options:['Se politiza la oposición','Desaparece la política','Se vuelve solo privada'],answer:0,reveal:'La intensidad amigo/enemigo convierte una diferencia en política.'},check:{prompt:'¿Cuál es el criterio de lo político?',options:['Distinción pública amigo/enemigo','Maximización de utilidad','Distribución proporcional'],answer:0}},
  {title:'Hostis, no inimicus',hook:'El enemigo político es una colectividad pública potencialmente combatiente, no cualquier persona que me desagrada.',body:'Schmitt distingue Feind público de inimicus privado. El enemigo político puede no ser moralmente malo ni personalmente odiado. Esto evita reducir la categoría a enemistad psicológica, aunque mantiene una concepción intensamente conflictiva de política.',relation:['diferencia privada','inimicus','enemigo público','hostis / Feind'],terms:[['hostis','','enemigo público'],['inimicus','','enemigo privado'],['Feind','','enemigo político'],['Öffentlichkeit','','carácter público']],quote:{original:'Feind ist nur der öffentliche Feind.',translation:'«Enemigo es solo el enemigo público».',source:'Der Begriff des Politischen',note:'La distinción excluye enemistades meramente personales.'},example:'Dos parlamentarios pueden odiarse personalmente sin que sus familias constituyan enemigos políticos.',tip:'No psicologices Freund/Feind.',discovery:{scenario:'Dos vecinos se detestan por una disputa de medianera sin organizar colectividades políticas.',question:'¿Son Feinde en sentido schmittiano?',options:['No','Sí necesariamente','Solo si hay juicio'],answer:0,reveal:'La enemistad política exige dimensión pública colectiva.'},check:{prompt:'¿Qué distingue Feind de inimicus?',options:['El carácter público y colectivo','La intensidad emocional privada','La antigüedad del conflicto'],answer:0}},
  {title:'La posibilidad real del conflicto extremo',hook:'La distinción política alcanza su límite en la posibilidad de combate entre colectividades.',body:'Schmitt no afirma que política sea guerra permanente. Sostiene que la posibilidad real de conflicto físico extremo da a la oposición política su seriedad específica. Si esa posibilidad desapareciera por completo, la distinción perdería intensidad política.',relation:['enemistad pública','posibilidad real de combate','riesgo existencial','intensidad política'],terms:[['Kampf','','combate'],['reale Möglichkeit','','posibilidad real'],['Existenz','','existencia'],['Intensität','','intensidad']],quote:{original:'Die Begriffe Freund, Feind und Kampf erhalten ihren realen Sinn ...',translation:'«Amigo, enemigo y lucha reciben su sentido real ...».',source:'Der Begriff des Politischen',note:'El conflicto extremo funciona como posibilidad límite, no como recomendación de guerra constante.'},example:'Una rivalidad deportiva intensa sigue siendo juego si nadie la trata como amenaza a existencia colectiva.',tip:'Diferenciá posibilidad límite y situación permanente.',discovery:{scenario:'Dos grupos compiten ferozmente, pero ambos excluyen por principio cualquier conflicto existencial y aceptan siempre una autoridad común.',question:'¿Qué disminuye?',options:['La intensidad específicamente política','La economía','La legalidad'],answer:0,reveal:'La posibilidad real de conflicto extremo es el horizonte límite de la distinción.'},check:{prompt:'¿Política equivale a guerra permanente?',options:['No; la guerra es posibilidad límite que da seriedad a la distinción','Sí, toda política es combate físico continuo','No existe relación alguna'],answer:0}},
  {title:'El Estado presupone el concepto de lo político',hook:'Schmitt invierte la idea de definir política simplemente por lo que hace el Estado.',body:'La frase “el concepto de Estado presupone el concepto de lo político” significa que el Estado es una forma histórica de organizar una unidad política ya constituida. Lo político puede emerger en conflictos que desbordan instituciones estatales.',relation:['agrupación política','unidad','Estado','orden institucional'],terms:[['Staat','','Estado'],['politische Einheit','','unidad política'],['das Politische','','lo político'],['Ordnung','','orden']],quote:{original:'Der Begriff des Staates setzt den Begriff des Politischen voraus.',translation:'«El concepto de Estado presupone el concepto de lo político».',source:'Der Begriff des Politischen',note:'Schmitt rechaza identificar sin resto política y aparato estatal.'},example:'Una guerra civil puede producir agrupaciones políticas poderosas precisamente cuando el Estado deja de monopolizar la unidad.',tip:'Primero preguntá dónde está la unidad política efectiva.',discovery:{scenario:'El aparato estatal existe formalmente, pero la población se divide en unidades rivales que ya no reconocen una autoridad común.',question:'¿Puede lo político desplazarse fuera del Estado?',options:['Sí','No nunca','Solo en elecciones'],answer:0,reveal:'La unidad política no se reduce a la existencia formal del aparato estatal.'},check:{prompt:'¿Qué presupone el Estado?',options:['Una unidad política previa o efectiva','Una economía de mercado específica','Una moral universal compartida'],answer:0}},
  {title:'Identität und Repräsentation',hook:'En la Teoría de la Constitución, toda forma política combina momentos de identidad y representación.',body:'Democracia enfatiza identidad del pueblo consigo mismo; representación hace presente una unidad política mediante personas o instituciones que la encarnan. Ningún Estado moderno funciona solo con uno de los polos de manera pura.',relation:['pueblo político','Identität','Repräsentation','forma del Estado'],terms:[['Identität','','identidad'],['Repräsentation','','representación'],['Volk','','pueblo'],['politische Form','','forma política']],quote:{original:'Identität und Repräsentation',translation:'«Identidad y representación».',source:'Verfassungslehre, 1928',note:'Son principios de forma política, no simples técnicas electorales.'},example:'Una asamblea representativa hace presente la unidad política sin reunir físicamente a todo el pueblo.',tip:'Representación schmittiana es más densa que delegación de preferencias.',discovery:{scenario:'Millones de ciudadanos no pueden actuar simultáneamente como una única persona, pero una institución habla en nombre de la unidad política.',question:'¿Qué principio opera?',options:['Repräsentation','Conatus','Pitié'],answer:0,reveal:'La representación hace presente una unidad ausente físicamente.'},check:{prompt:'¿Qué polos estructuran la forma política?',options:['Identidad y representación','Mercado y familia','Moralidad y felicidad'],answer:0}},
  {title:'Poder constituyente y decisión constitucional',hook:'La constitución en sentido positivo expresa una decisión fundamental sobre forma y modo de existencia política.',body:'Schmitt distingue Verfassung de simples Verfassungsgesetze. La constitución descansa en una decisión del pouvoir constituant sobre unidad política, mientras leyes constitucionales regulan aspectos dentro de esa decisión fundamental.',relation:['pouvoir constituant','decisión fundamental','Verfassung','leyes constitucionales'],terms:[['verfassunggebende Gewalt','','poder constituyente'],['Verfassung','','constitución'],['Verfassungsgesetz','','ley constitucional'],['politische Entscheidung','','decisión política']],quote:{original:'Die Verfassung im positiven Sinne enthält ... die Entscheidung über Art und Form der politischen Einheit.',translation:'«La constitución contiene la decisión sobre tipo y forma de la unidad política».',source:'Verfassungslehre, §3',note:'Schmitt separa núcleo político constituyente y normas constitucionales particulares.'},example:'Cambiar el plazo de una comisión no equivale a decidir si la unidad política será monárquica, republicana o federal.',tip:'Cerrá el sistema distinguiendo norma, decisión y poder constituyente.',discovery:{scenario:'Una comunidad cambia un detalle procedimental sin alterar quién constituye la unidad política ni su forma básica.',question:'¿Es necesariamente una nueva decisión constituyente?',options:['No','Sí siempre','Solo si lo ordena un juez'],answer:0,reveal:'Schmitt distingue leyes constitucionales y decisión constitucional fundamental.'},check:{prompt:'¿Qué expresa Verfassung en sentido positivo?',options:['Una decisión fundamental del poder constituyente sobre la unidad política','Cualquier reglamento administrativo','Solo jurisprudencia ordinaria'],answer:0}}
 ]});

 add({id:'arendt',prefix:'an',author:'Hannah Arendt',work:'La condición humana + Sobre la revolución + Sobre la violencia + Los orígenes del totalitarismo',workId:'human-condition',icon:'🕊️',tagline:'Pluralidad, acción, natalidad, poder, revolución y totalitarismo',lessons:[
  {title:'Vita activa: labor, work, action',hook:'Arendt separa tres actividades humanas para evitar reducir toda vida política a producción o supervivencia.',body:'Labor responde al ciclo biológico; work construye un mundo relativamente durable; action ocurre directamente entre personas plurales y abre un espacio político. Cada actividad tiene lógica y temporalidad distintas.',relation:['labor','work','mundo durable','action entre plurales'],terms:[['labor','','labor / actividad biológica'],['work','','obra / fabricación'],['action','','acción'],['vita activa','','vida activa']],quote:{original:'With the term vita activa, I propose to designate three fundamental human activities: labor, work, and action.',translation:'«Con vita activa designo tres actividades fundamentales: labor, obra y acción».',source:'The Human Condition, §1',note:'La distinción impide tratar toda práctica humana como producción instrumental.'},example:'Cultivar alimentos, construir una mesa y fundar un consejo ciudadano son actividades con lógicas diferentes.',tip:'No confundas action con “hacer cosas” en general.',discovery:{scenario:'Una teoría describe deliberar, fabricar herramientas y alimentarse como si fueran la misma clase de actividad.',question:'¿Qué distinción arendtiana falta?',options:['Labor / work / action','Amigo / enemigo','Derecho / ley natural'],answer:0,reveal:'La vita activa contiene actividades irreductibles entre sí.'},check:{prompt:'¿Cuáles son las tres actividades fundamentales?',options:['Labor, work y action','Propiedad, contrato y soberanía','Familia, mercado y Estado'],answer:0}},
  {title:'Labor y work: vida versus mundo',hook:'Labor mantiene procesos vitales; work fabrica objetos que estabilizan un mundo humano.',body:'Animal laborans consume y reproduce la vida en ciclos. Homo faber produce un mundo de artefactos relativamente durables mediante lógica medios-fines. La política se empobrece si queda absorbida por necesidad biológica o instrumentalidad.',relation:['necesidad vital','labor','durabilidad artificial','work'],terms:[['animal laborans','','ser humano como laborante'],['homo faber','','ser humano como fabricante'],['worldliness','','mundanidad'],['durability','','durabilidad']],quote:{original:'Work provides an “artificial” world of things, distinctly different from all natural surroundings.',translation:'«La obra proporciona un mundo artificial de cosas distinto del entorno natural».',source:'The Human Condition, cap. IV',note:'El mundo durable ofrece escenario a la acción y memoria.'},example:'Un edificio público dura más que la actividad biológica diaria y puede hospedar generaciones de acción política.',tip:'El mundo común necesita durabilidad, pero fabricar no equivale todavía a actuar políticamente.',discovery:{scenario:'Una sociedad produce sin descanso bienes consumibles, pero carece de espacios y objetos durables compartidos.',question:'¿Qué dimensión se debilita?',options:['Worldliness','Soberanía','Ley eterna'],answer:0,reveal:'Work crea un mundo estable que no se consume inmediatamente.'},check:{prompt:'¿Qué distingue work de labor?',options:['Produce un mundo relativamente durable','Es puro proceso biológico','Es idéntico a acción política'],answer:0}},
  {title:'Plurality: condición de la acción',hook:'La acción política existe porque somos iguales para entendernos y distintos para aparecer como quiénes somos.',body:'Plurality combina igualdad y distinción. Actuar y hablar ante otros revela un “quién” imprevisible que no puede reducirse a función social. La política necesita un mundo compartido entre personas no idénticas.',relation:['igualdad humana','distinción','speech/action','plurality'],terms:[['plurality','','pluralidad'],['speech','','discurso / palabra'],['action','','acción'],['who','','quién']],quote:{original:'Plurality is the condition of human action.',translation:'«La pluralidad es la condición de la acción humana».',source:'The Human Condition, §1',note:'Pluralidad no significa simple diversidad sociológica; es condición ontológica de aparecer entre iguales distintos.'},example:'Si todos fueran copias idénticas, deliberar y revelar perspectivas distintas perdería sentido.',tip:'Acción y pluralidad se implican mutuamente.',discovery:{scenario:'Una comunidad elimina toda diferencia de perspectiva y convierte a las personas en ejecutores intercambiables.',question:'¿Qué condición política destruye?',options:['Plurality','Property','Natural law'],answer:0,reveal:'La acción necesita iguales que sean irreductiblemente distintos.'},check:{prompt:'¿Qué es condición de human action?',options:['Pluralidad','Aislamiento','Homogeneidad completa'],answer:0}},
  {title:'Natality: capacidad de comenzar',hook:'La política posee una temporalidad de inicio: actuar puede introducir algo nuevo que no se deduce del pasado.',body:'Natality designa la capacidad humana de comenzar porque cada nacimiento introduce un nuevo actor en el mundo. La acción es imprevisible y puede iniciar procesos que ningún agente controla totalmente.',relation:['nacimiento','nuevo actor','initium','acción imprevisible'],terms:[['natality','','natalidad'],['beginning','','comienzo'],['initium','','inicio'],['novelty','','novedad']],quote:{original:'The new beginning inherent in birth can make itself felt in the world only because the newcomer possesses the capacity of beginning something anew.',translation:'«El nuevo comienzo del nacimiento puede hacerse sentir porque el recién llegado puede comenzar algo nuevo».',source:'The Human Condition, cap. V',note:'Natalidad desplaza el foco filosófico desde mortalidad hacia capacidad de inicio.'},example:'Una revolución o fundación política puede abrir posibilidades que no estaban predeterminadas por estructuras previas.',tip:'Natalidad no niega condicionamientos; subraya capacidad de inicio dentro de ellos.',discovery:{scenario:'Una teoría afirma que todo acontecimiento político está completamente predeterminado por causas anteriores.',question:'¿Qué dimensión arendtiana pierde?',options:['Natality','Property','Sovereignty'],answer:0,reveal:'La acción puede iniciar procesos nuevos e imprevisibles.'},check:{prompt:'¿Qué expresa natality?',options:['Capacidad de comenzar algo nuevo','Repetición biológica sin novedad','Obediencia a tradición'],answer:0}},
  {title:'Public realm y space of appearance',hook:'La política necesita un espacio donde personas aparezcan unas ante otras mediante palabra y acción.',body:'El public realm no es solo un edificio estatal. Surge allí donde personas actúan y hablan juntas ante una audiencia plural. Ese space of appearance es frágil: existe mientras la interacción pública se sostiene.',relation:['pluralidad reunida','speech/action','aparición pública','mundo común'],terms:[['public realm','','espacio público'],['space of appearance','','espacio de aparición'],['common world','','mundo común'],['visibility','','visibilidad']],quote:{original:'The space of appearance comes into being wherever men are together in the manner of speech and action.',translation:'«El espacio de aparición surge donde las personas están juntas mediante palabra y acción».',source:'The Human Condition, cap. V',note:'El espacio político es relacional antes que meramente arquitectónico.'},example:'Una plaza vacía no es por sí misma esfera pública; se vuelve política cuando personas aparecen, hablan y actúan juntas.',tip:'Buscá relaciones de aparición, no solo instituciones formales.',discovery:{scenario:'Miles de personas viven juntas pero nunca pueden hablar ni aparecer públicamente unas ante otras.',question:'¿Qué falta?',options:['Space of appearance','Mercado','Soberanía absoluta'],answer:0,reveal:'La coexistencia física no basta para un espacio político.'},check:{prompt:'¿Cuándo surge el espacio de aparición?',options:['Cuando personas actúan y hablan juntas','Cuando existe cualquier edificio estatal','Cuando todos permanecen privados'],answer:0}},
  {title:'Power versus violence',hook:'Poder y violencia no son sinónimos: el poder nace de actuar en conjunto, la violencia es instrumental.',body:'Power corresponde a capacidad humana de actuar concertadamente y depende de apoyo continuo. Violence utiliza instrumentos para imponer. La violencia puede destruir poder, pero no producir por sí sola la legitimidad y acción conjunta que lo sostienen.',relation:['acting in concert','power','pérdida de apoyo','violence'],terms:[['power','','poder'],['violence','','violencia'],['acting in concert','','actuar concertadamente'],['support','','apoyo']],quote:{original:'Power and violence are opposites.',translation:'«Poder y violencia son opuestos».',source:'On Violence, III',note:'Arendt distingue conceptualmente fenómenos que empíricamente pueden aparecer juntos.'},example:'Un gobierno puede poseer armas enormes y, sin apoyo de ejército, funcionarios ni población, descubrir que su poder se evaporó.',tip:'Medí poder por capacidad de acción conjunta, no solo por arsenal.',discovery:{scenario:'Un régimen necesita aumentar coerción cada día porque perdió casi todo apoyo organizado.',question:'¿Está aumentando necesariamente su power?',options:['No','Sí, violencia y poder son idénticos','Solo si hay elecciones'],answer:0,reveal:'La violencia puede compensar temporalmente una pérdida de poder, no reemplazarlo sin límite.'},check:{prompt:'¿De dónde surge power?',options:['De personas actuando concertadamente','De armas por sí solas','De riqueza privada únicamente'],answer:0}},
  {title:'Revolution: libertad pública, no solo liberación',hook:'Las revoluciones pueden liberar de opresión y aun fracasar en fundar espacios durables de libertad política.',body:'Arendt distingue liberation de freedom. Liberarse de una dominación es condición, pero la revolución alcanza su promesa cuando funda instituciones donde ciudadanía participa en asuntos públicos. Los consejos le interesan como formas de esa experiencia.',relation:['liberation','fundación','participación pública','freedom'],terms:[['liberation','','liberación'],['freedom','','libertad política'],['public happiness','','felicidad pública'],['councils','','consejos']],quote:{original:'Liberation may be the condition of freedom but by no means leads automatically to it.',translation:'«La liberación puede ser condición de libertad, pero no conduce automáticamente a ella».',source:'On Revolution, cap. 1',note:'La libertad requiere institución de un espacio público de acción.'},example:'Derribar un régimen opresivo no garantiza que la población obtenga después instituciones para deliberar y actuar públicamente.',tip:'Preguntá qué se funda después de la liberación.',discovery:{scenario:'Una revolución expulsa al tirano y luego concentra toda decisión en una burocracia sin participación pública.',question:'¿Se realizó plenamente la freedom arendtiana?',options:['No','Sí, liberación basta','Solo si hay crecimiento económico'],answer:0,reveal:'La libertad política exige instituciones de acción pública.'},check:{prompt:'¿Qué diferencia libertad de liberación?',options:['La libertad requiere fundar participación pública durable','Son exactamente lo mismo','La libertad es solo privada'],answer:0}},
  {title:'Totalitarianism: ideología, terror y destrucción de pluralidad',hook:'El totalitarismo no es simplemente dictadura más intensa: busca transformar condiciones de acción humana.',body:'Arendt analiza una forma de dominación que combina ideology y terror, destruye espontaneidad, aísla individuos y erosiona mundo común. El objetivo no es solo prohibir oposición, sino volver superflua la capacidad de comenzar y actuar pluralmente.',relation:['ideology','terror','isolation/loneliness','destrucción de acción plural'],terms:[['totalitarianism','','totalitarismo'],['ideology','','ideología'],['terror','','terror'],['loneliness','','soledad / desarraigo']],quote:{original:'Terror is the essence of totalitarian domination.',translation:'«El terror es la esencia de la dominación totalitaria».',source:'The Origins of Totalitarianism, III',note:'El terror opera junto con ideología y atomización social.'},example:'Un régimen totalitario no se conforma con obediencia exterior: pretende volver imposible la espontaneidad y el mundo común entre personas.',tip:'Cerrá el sistema conectando totalitarismo con la destrucción de pluralidad y natalidad.',discovery:{scenario:'Un régimen busca no solo silenciar opositores sino impedir cualquier vínculo espontáneo entre ciudadanos.',question:'¿Qué condición humana ataca?',options:['Pluralidad y acción','Propiedad únicamente','Ley natural'],answer:0,reveal:'El totalitarismo erosiona las condiciones mismas de un mundo político común.'},check:{prompt:'¿Qué distingue la dominación totalitaria?',options:['Ideología y terror orientados a destruir pluralidad y espontaneidad','Simple gobierno representativo','Mercado regulado'],answer:0}}
 ]});
 window.POLIS_ORDER_SYSTEMS?.(['plato','aristotle','augustine','aquinas','machiavelli','spinoza','hobbes','locke','rousseau','kant','hegel','marx','schmitt','arendt']);
})();
